input.command:
cd "C:/WINDOWS/TEMP/claude/bundled-skills/2.1.308/6bd652eb2e9f946627c46d0d527ad591/dataviz" && python3 - << 'EOF' 2>/dev/null || python - << 'EOF2'
EOF
node -e '
const stops=["#86b6ef","#6da7ec","#5598e7","#3987e5","#2a78d6","#256abf","#1c5cab","#184f95","#104281","#0d366b"];
const h=s=>[1,3,5].map(i=>parseInt(s.slice(i,i+2),16));
const hex=v=>"#"+v.map(x=>Math.round(x).toString(16).padStart(2,"0")).join("");
const out=[];const N=12;
for(let k=0;k<N;k++){const t=k/(N-1)*(stops.length-1);const i=Math.min(Math.floor(t),stops.length-2);const f=t-i;
const a=h(stops[i]),b=h(stops[i+1]);out.push(hex(a.map((x,j)=>x+(b[j]-x)*f)));}
console.log(out.join(","));
' > "$HOME/raman_analysis/ramp.txt"; cat "$HOME/raman_analysis/ramp.txt"; node scripts/validate_palette.js "$(cat $HOME/raman_analysis/ramp.txt)" --mode light --ordinal 2>&1 | head -60

